import{_ as e,c as a,d as n,Z as l}from"./chunks/framework.B0uuYL3Y.js";const o="/microarch/spectre-v1-timeline.png",b=JSON.parse('{"title":"Spectre v1 中的边界检查为何会被越过","description":"从一段 C 代码和实际反汇编出发，逐条看分支尚未确认时加载如何越过软件边界。","frontmatter":{"title":"Spectre v1 中的边界检查为何会被越过","description":"从一段 C 代码和实际反汇编出发，逐条看分支尚未确认时加载如何越过软件边界。","date":"2026-11-25","tags":["微架构安全","Spectre","分支预测","瞬态执行"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-04d-spectre-v1.md","filePath":"posts/microarch-04d-spectre-v1.md"}'),c={name:"posts/microarch-04d-spectre-v1.md"};function t(p,s,r,d,i,h){return a(),n("div",null,s[0]||(s[0]=[l(`<p>一个函数只允许读表的前四个元素。传入下标 5，函数最后正确返回 0。这个返回值能说明程序遵守了边界检查。它还留下一个问题：在确定应该返回 0 以前，处理器有没有先向缓存请求过第六个元素所在的行？Spectre v1 的边界检查绕过，发生在这两个时刻之间。</p><p>回想<a href="./microarch-03a-fetch-prediction.html#predict-pht">条件分支的方向预测</a>与<a href="./microarch-03a-fetch-prediction.html#predict-fetch">取指地址预测</a>。前端可以在比较结果就绪之前，先把预测路径上的指令送入流水线。本节选用一段很短的读取函数，把这件事落实到具体指令。</p><nav class="table-of-contents"><ul><li><a href="#源码里的边界对应哪条分支">源码里的边界对应哪条分支</a></li><li><a href="#比较还在等待-加载为什么能先发出">比较还在等待，加载为什么能先发出</a></li><li><a href="#从一次错路径加载到漏洞结论-中间还差什么">从一次错路径加载到漏洞结论，中间还差什么</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="源码里的边界对应哪条分支" tabindex="-1">源码里的边界对应哪条分支 <a class="header-anchor" href="#源码里的边界对应哪条分支" aria-label="Permalink to &quot;源码里的边界对应哪条分支&quot;">​</a></h2><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">#include</span><span style="color:#2AA198;"> &lt;stddef.h&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">unsigned</span><span style="color:#268BD2;"> read_sample</span><span style="color:#839496;">(</span><span style="color:#93A1A1;font-weight:bold;">const</span><span style="color:#93A1A1;font-weight:bold;"> unsigned</span><span style="color:#859900;"> *</span><span style="color:#839496;">samples, </span><span style="color:#93A1A1;font-weight:bold;">const</span><span style="color:#93A1A1;font-weight:bold;"> unsigned</span><span style="color:#859900;"> *</span><span style="color:#839496;">visible, </span><span style="color:#93A1A1;font-weight:bold;">size_t</span><span style="color:#839496;"> index) {</span></span>
<span class="line"><span style="color:#859900;">    if</span><span style="color:#839496;"> (index </span><span style="color:#859900;">&gt;=</span><span style="color:#859900;"> *</span><span style="color:#839496;">visible)</span></span>
<span class="line"><span style="color:#859900;">        return</span><span style="color:#D33682;"> 0</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#859900;">    return</span><span style="color:#839496;"> samples[index];</span></span>
<span class="line"><span style="color:#839496;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>题设中，<code>samples</code> 指向八个 32 位无符号整数，内容依次为 11、22、33、44、55、66、77、88。变量 <code>*visible</code> 的值为 4，在一次调用期间不变。前四项是函数允许返回的数据，后四项只用来说明逻辑边界，所有元素都放在同一个实际数组里。</p><p>下面是这段源码的实际反汇编。GCC 15.2.0，目标 <code>x86_64-w64-mingw32</code>，选项 <code>-O2 -c</code>，用 <code>objdump -d -Mintel</code> 读取对象文件。左边是指令相对于函数开头的十六进制偏移。Windows x64 调用约定把前三个参数分别放在 <code>rcx</code>、<code>rdx</code>、<code>r8</code>。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>00  xor eax, eax</span></span>
<span class="line"><span>02  mov edx, DWORD PTR [rdx]</span></span>
<span class="line"><span>04  cmp r8, rdx</span></span>
<span class="line"><span>07  jae 0x0d</span></span>
<span class="line"><span>09  mov eax, DWORD PTR [rcx+r8*4]</span></span>
<span class="line"><span>0d  ret</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>第一条把返回值预先置为 0。偏移 <code>02</code> 的指令从 <code>rdx</code> 指向的位置读出 4，写入 <code>edx</code> 时把 <code>rdx</code> 的高 32 位清零。偏移 <code>04</code> 的比较据此设置标志位。接着 <code>jae</code> 按<strong>无符号</strong>比较，在 <code>index &gt;= 4</code> 时跳到 <code>0d</code>。因此，这条机器指令预测为<strong>跳转</strong>表示预计会拒绝下标，预测为<strong>不跳转</strong>表示预计会执行 <code>09</code> 的数据加载。</p><p>具体看 <code>CF</code>，也就是这里用于表示无符号减法借位的标志。下标为 2 时，<code>cmp</code> 计算 <code>2 - 4</code> 所对应的标志，<code>CF = 1</code>，所以 <code>jae</code> 不跳。偏移 <code>09</code> 从基址加 8 的位置取出 33，覆盖 <code>eax</code> 里的 0。下标为 5 时，<code>cmp</code> 比较 <code>5 - 4</code>，<code>CF = 0</code>，所以 <code>jae</code> 直接去 <code>0d</code>。在这条路径上，<code>ret</code> 返回调用者，调用者从 <code>eax</code> 取得预置的 0。</p><table tabindex="0"><thead><tr><th>输入</th><th>真实分支方向</th><th>指令 <code>09</code> 在程序语义上是否执行</th><th>返回值</th></tr></thead><tbody><tr><td><code>index = 2</code></td><td>不跳转</td><td>读取 <code>samples[2]</code></td><td>33</td></tr><tr><td><code>index = 5</code></td><td>跳转</td><td>跳过这条指令</td><td>0</td></tr></tbody></table><details class="details custom-block"><summary>完整的正常调用</summary><p>把下面的 <code>main</code> 和前面的 <code>read_sample</code> 一起编译。它用同一张公开表验证两个返回值。</p><div class="language-c line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">#include</span><span style="color:#2AA198;"> &lt;assert.h&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">int</span><span style="color:#268BD2;"> main</span><span style="color:#839496;">(</span><span style="color:#93A1A1;font-weight:bold;">void</span><span style="color:#839496;">) {</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    const</span><span style="color:#93A1A1;font-weight:bold;"> unsigned</span><span style="color:#839496;"> samples</span><span style="color:#93A1A1;font-weight:bold;">[]</span><span style="color:#859900;"> =</span><span style="color:#839496;"> {</span><span style="color:#D33682;">11</span><span style="color:#839496;">, </span><span style="color:#D33682;">22</span><span style="color:#839496;">, </span><span style="color:#D33682;">33</span><span style="color:#839496;">, </span><span style="color:#D33682;">44</span><span style="color:#839496;">, </span><span style="color:#D33682;">55</span><span style="color:#839496;">, </span><span style="color:#D33682;">66</span><span style="color:#839496;">, </span><span style="color:#D33682;">77</span><span style="color:#839496;">, </span><span style="color:#D33682;">88</span><span style="color:#839496;">};</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    const</span><span style="color:#93A1A1;font-weight:bold;"> unsigned</span><span style="color:#839496;"> visible </span><span style="color:#859900;">=</span><span style="color:#D33682;"> 4</span><span style="color:#839496;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    unsigned</span><span style="color:#839496;"> accepted </span><span style="color:#859900;">=</span><span style="color:#268BD2;"> read_sample</span><span style="color:#839496;">(samples, </span><span style="color:#859900;">&amp;</span><span style="color:#839496;">visible, </span><span style="color:#D33682;">2</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">    unsigned</span><span style="color:#839496;"> rejected </span><span style="color:#859900;">=</span><span style="color:#268BD2;"> read_sample</span><span style="color:#839496;">(samples, </span><span style="color:#859900;">&amp;</span><span style="color:#839496;">visible, </span><span style="color:#D33682;">5</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#268BD2;">    assert</span><span style="color:#839496;">(accepted </span><span style="color:#859900;">==</span><span style="color:#D33682;"> 33</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#268BD2;">    assert</span><span style="color:#839496;">(rejected </span><span style="color:#859900;">==</span><span style="color:#D33682;"> 0</span><span style="color:#839496;">);</span></span>
<span class="line"><span style="color:#859900;">    return</span><span style="color:#D33682;"> 0</span><span style="color:#839496;">;</span></span>
<span class="line"><span style="color:#839496;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>两个调用传入相同的数组和边界。只有第三个参数改变。断言核对的是函数的架构结果，表中的推测过程另用下一节的模型说明。</p></details><h2 id="比较还在等待-加载为什么能先发出" tabindex="-1">比较还在等待，加载为什么能先发出 <a class="header-anchor" href="#比较还在等待-加载为什么能先发出" aria-label="Permalink to &quot;比较还在等待，加载为什么能先发出&quot;">​</a></h2><p>注意 <code>09</code> 的内存地址只用到了 <code>rcx</code> 和 <code>r8</code>。一旦两个参数就绪，地址生成不需要先读到 <code>*visible</code>。制约它的是前面的控制流。处理器推测走哪条路径后，就可以尝试发射这条加载。比较仍然要按真实数据完成，随后才知道这条路径是否应该成立。</p><p>用 <code>index = 5</code> 走一次。假定预测器给出“不跳转”，且读取边界值很慢。为便于计算，令数组首地址为 <code>0x2030</code>，缓存行长为 64 字节，下表沿用同一页内的地址表示。下标 5 对应地址 <code>0x2030 + 5 × 4 = 0x2044</code>，落在从 <code>0x2040</code> 开始的行。前四项位于从 <code>0x2000</code> 开始的行。这些地址和先后顺序是题设。反汇编给出的是指令与依赖关系。</p><figure class="lesson-figure"><a href="/microarch/spectre-v1-timeline.png" aria-label="查看完整时序图"><img src="`+o+'" width="820" height="540" loading="lazy" alt="四步教学时序。前端预测不跳转，偏移 09 请求 0x2044，比较 5 与 4 后跳到 0d，最后返回 0。如果请求已经填充 0x2040，这条缓存行仍可能驻留。"></a><figcaption>先对照第 2、3 步。偏移 <code>09</code> 的地址已经就绪，真实方向还没确认。第 4 步分别看正确的返回值和可能留下的缓存状态。图按本节题设绘制。</figcaption></figure><table tabindex="0"><thead><tr><th>次序</th><th>边界检查一侧</th><th>预测路径一侧</th></tr></thead><tbody><tr><td>1</td><td>读取 <code>*visible</code>，比较尚未就绪</td><td>前端预测不跳转，把 <code>09</code> 的加载送入后端</td></tr><tr><td>2</td><td><code>jae</code> 仍在等比较</td><td>加载所需的两个参数齐备，可以向缓存请求 <code>0x2044</code></td></tr><tr><td>3</td><td><code>*visible</code> 返回 4，比较确认 5 大于等于 4</td><td>前端改到 <code>0d</code>，丢弃错误路径加载的结果</td></tr><tr><td>4</td><td>正确路径执行返回</td><td>已发出的请求是否完成、是否改变了缓存，取决于缓存收到请求时的状态与实现</td></tr></tbody></table><p>假定 <code>0x2040</code> 最初没有驻留，且第 2 步的读取在第 3 步之前已成功填充。缓存里可能已经多出这一行，错误路径的 <code>eax</code> 也可能暂时拿到数组元素 66。分支恢复时，处理器丢弃这个较年轻的寄存器版本，让正确路径继续使用先前的 0。行填充由缓存控制器处理，恢复寄存器并不自动撤销这项填充。如果请求还在途，应按<a href="./microarch-01a-mshr.html">未命中与 MSHR</a>分析缓存端当时的状态。</p><p>这个例子中的缓存地址由下标决定。保持下标为 5，把元素 66 换成 17，读取的仍是 <code>0x2044</code>。因此这里的行填充只能说明读取路径可能发生过，无法从这一条行判断里面是 66 还是 17。历史漏洞还涉及值怎样影响其他可观察的活动，必须单独证明这一段依赖。</p><h2 id="从一次错路径加载到漏洞结论-中间还差什么" tabindex="-1">从一次错路径加载到漏洞结论，中间还差什么 <a class="header-anchor" href="#从一次错路径加载到漏洞结论-中间还差什么" aria-label="Permalink to &quot;从一次错路径加载到漏洞结论，中间还差什么&quot;">​</a></h2><p>上面的例子只改变了能否越过函数自己的访问边界。整张表的页仍允许当前程序读取，所以地址翻译和页权限可以正常通过。在实际漏洞中，软件检查承担着隔离数据或对象的职责，越过它才有安全含义。还必须说明瞬态访问如何改变可观察的状态，以及观察者能从这种差异得到什么。只发现一次分支误预测，不能推出后续加载已发出。只发现一次行填充，也不能推出它来自这条加载，因为<a href="./microarch-02-prefetch.html#prefetch-queue">预取</a>等路径也可能带来填充。</p><details class="details custom-block"><summary>练习：把边界值的等待去掉</summary><p>仍输入下标 5，预测仍是不跳。现在把题设改成比较在 <code>09</code> 能发出请求之前就完成。还会返回什么？能否用 <code>09</code> 解释此时发现 <code>0x2040</code> 已在缓存里？</p><p>函数仍返回 0。由于题设给定了错误路径加载在发请求之前被撤销，这次 <code>09</code> 不能解释该行的驻留。可以回头检查先前访问、预取或测量本身。决定结果的是两件事的先后，即真实方向确认与错误路径请求实际发出。</p></details><p>如果一份记录只有「分支错预测数增加、L1 填充数增加、最后返回 0」，可以先用上述时间线判断它能说明什么。最后一项符合正常恢复。前两项是计数，还需要确认计到哪条分支、哪次访问和哪个请求来源。查读器件计数时，可接着看<a href="./microarch-04a-measurement.html">计时和计数器的归因例题</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://spectreattack.com/spectre.pdf" target="_blank" rel="noreferrer">Spectre 原论文</a></li><li><a href="https://learn.microsoft.com/en-us/cpp/build/x64-calling-convention?view=msvc-170#parameter-passing" target="_blank" rel="noreferrer">Microsoft 的 x64 参数约定</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/software-security-guidance/technical-documentation/analysis-speculative-execution-side-channels.html#variant-1-bounds-check-bypass" target="_blank" rel="noreferrer">Intel 对 Bounds Check Bypass 的说明</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/software-security-guidance/technical-documentation/hardware-behavior-related-to-speculative-execution.html" target="_blank" rel="noreferrer">Intel 推测执行与恢复说明</a></li><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html" target="_blank" rel="noreferrer">Intel 指令集手册，CMP、Jcc 与通用寄存器写入规则</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-06d-core-scheduling.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>同核多线程怎样安排任务</strong></span></a></p><p><a href="./microarch-04e-meltdown.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>Meltdown 中的越权加载如何影响后续指令</strong></span></a></p></nav>',26)]))}const y=e(c,[["render",t]]);export{b as __pageData,y as default};
